import type { SurfZoneHost } from '../game/SurfZoneHost';
import type { CanyonApproach } from '../wave/canyonStandingApproach';
import type { SurfZoneConfig } from '../wave/SurfZoneSimulation';
import { SURF_ZONE_STEP } from '../wave/SurfZoneRunner';
import { decompress } from '../wave/surfZoneState';
import type { PhysicalMode } from '../game/PhysicalMode';

interface StandingRecording extends CanyonApproach {
  config: SurfZoneConfig;
  sea: Uint8Array;
}

/** The recording generated by the standing-start exercise in scripts/canyon-balance.ts. */
export async function loadCanyonStanding(): Promise<StandingRecording> {
  const [metadata, water] = await Promise.all([
    fetch('/debug/canyon/standing.json'), fetch('/debug/canyon/approach.sea'),
  ]);
  if (!metadata.ok || !water.ok) throw new Error('The Canyon standing recording could not be loaded.');
  const { config, approachPlacement, approachInputs } = await metadata.json() as Omit<StandingRecording, 'sea'>;
  if (config?.spot !== 'canyon' || config.seed !== 2 || config.stage !== 2 || config.compute !== 'cpu'
    || config.turnBalance !== 'planing' || approachPlacement?.phase !== 'prone'
    || ![approachPlacement.x, approachPlacement.z, approachPlacement.heading, approachPlacement.speed].every(Number.isFinite)
    || !Array.isArray(approachInputs) || !approachInputs.length
    || !approachInputs.every(row => Number.isSafeInteger(row.steps) && row.steps > 0
      && [row.paddle, row.sprint, row.popUp].every(value => typeof value === 'boolean'))) {
    throw new Error('The Canyon recording has invalid starting conditions.');
  }
  const sea = await decompress(new Uint8Array(await water.arrayBuffer()), true);
  return { config: { ...config, spinUpPeriods: 0 }, approachPlacement, approachInputs, sea };
}

/** Wait for the worker to publish the requested physics step. The in-page host publishes synchronously. */
async function waitForCanyonStep(host: Pick<SurfZoneHost, 'outstandingSteps'>): Promise<void> {
  const deadline = performance.now() + 30_000;
  while (host.outstandingSteps > 0) {
    if (performance.now() > deadline) throw new Error('The Canyon worker did not return the requested frame.');
    await new Promise(resolve => setTimeout(resolve, 16));
  }
}

export type CanyonSide = 'left' | 'right';
export interface CanyonTurnReading {
  elapsed: number;
  input: 'Settling' | 'Steering and compressing' | 'Released';
  phase: string;
  separation?: string;
  peakBank: number;
  peakCourseChange?: number;
  courseChangeAtRelease?: number;
}

/** Board-space controls, independent of the camera and the device driving it. */
export async function runStandingTurn(mode: Pick<PhysicalMode, 'host' | 'advance'>, side: CanyonSide,
  signal: AbortSignal, show: (reading: CanyonTurnReading) => void): Promise<void> {
  const host = mode.host;
  if (host?.snapshot.status.ride?.phase !== 'standing') throw new Error('The turn needs the standing start.');
  const degrees = 180 / Math.PI;
  const steerTick = Math.round(0.3 / SURF_ZONE_STEP);
  const releaseTick = Math.round(1.2 / SURF_ZONE_STEP);
  let peakBank = 0;
  let previousCourse: number | undefined;
  let courseChange = 0;
  let peakCourseChange: number | undefined;
  let courseChangeAtRelease: number | undefined;
  for (let tick = 0; tick < Math.round(3 / SURF_ZONE_STEP); tick++) {
    if (signal.aborted || mode.host !== host) return;
    const held = tick >= steerTick && tick < releaseTick;
    mode.advance(1, { paddle: false, popUp: false, steer: held ? (side === 'left' ? 1 : -1) : 0, compress: held ? 1 : 0 });
    const synchronous = host.outstandingSteps === 0;
    await waitForCanyonStep(host);
    if (signal.aborted || mode.host !== host) return;
    const ride = host.snapshot.status.ride!;
    const bank = (ride.bank ?? 0) * degrees;
    if (Math.abs(bank) > Math.abs(peakBank)) peakBank = bank;
    const { wave } = ride;
    if (ride.phase === 'standing' && tick + 1 >= steerTick && wave.speedOverGround > 0) {
      // The wave gauge rotates with the local swell. Put its velocity components back in the world frame.
      const course = Math.atan2(wave.directionX, wave.directionZ) + Math.atan2(wave.speedAlongCrest, wave.speedShoreward);
      if (previousCourse !== undefined) {
        const delta = course - previousCourse;
        courseChange += Math.atan2(Math.sin(delta), Math.cos(delta)) * degrees;
      }
      previousCourse = course;
      if (peakCourseChange === undefined || Math.abs(courseChange) > Math.abs(peakCourseChange)) peakCourseChange = courseChange;
      if (tick + 1 === releaseTick) courseChangeAtRelease = courseChange;
    }
    show({ elapsed: (tick + 1) * SURF_ZONE_STEP, input: held ? 'Steering and compressing' : tick < steerTick ? 'Settling' : 'Released',
      phase: ride.phase, separation: ride.separation, peakBank, peakCourseChange, courseChangeAtRelease });
    if (ride.phase !== 'standing') return;
    // The in-page host runs synchronously. Give the renderer the same chance to show its frames as the worker's.
    if (synchronous) await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
  }
}
